        p: [['O valor de $(−1) × (−1) × (−1) × (−1)$ é:', ['$−4$', '$−1$', '$1$', '$4$'], 2, 'Quatro negativos: positivo. <strong>Alternativa C.</strong>'], ['O valor de $(−2) × (−3) × 5$ é:', ['$−30$', '$−10$', '$10$', '$30$'], 3, 'Dois negativos: positivo. <strong>Alternativa D.</strong>'], ['O valor de $4 × (−5 + 2)$ é:', ['$−12$', '$−3$', '$12$', '$28$'], 0, '$4 × (−3) = −12$. <strong>Alternativa A.</strong>']],
