        q: [['$10 − 2 × 3$ é:', ['$24$', '$4$', '$16$', '$−4$'], 1], ['$(−1)^{5}$ é:', ['$−5$', '$5$', '$−1$', '$1$'], 2], ['$4 + (−3) × 2$ é:', ['$2$', '$−2$', '$10$', '$−10$'], 1], ['$−3^{2}$ é:', ['$9$', '$−9$', '$−6$', '$6$'], 1]],
